import{_ as a,o as s,c as n,a2 as p}from"./chunks/framework.vLhlLNVn.js";const u=JSON.parse('{"title":"第 4 章 MoE","description":"","frontmatter":{},"headers":[],"relativePath":"fundamentals/MoE.md","filePath":"fundamentals/MoE.md"}'),t={name:"fundamentals/MoE.md"};function o(i,e,l,c,d,r){return s(),n("div",null,[...e[0]||(e[0]=[p(`<h1 id="第-4-章-moe" tabindex="-1"><strong>第 4 章</strong> MoE <a class="header-anchor" href="#第-4-章-moe" aria-label="Permalink to &quot;**第 4 章** MoE&quot;">​</a></h1><h2 id="_1-moe做什么" tabindex="-1">1. MoE做什么？ <a class="header-anchor" href="#_1-moe做什么" aria-label="Permalink to &quot;1. MoE做什么？&quot;">​</a></h2><p>要计算的就是每个expert的FFN。</p><p>普通Transformer中，每个token都经过同一个FFN：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>x → Linear → 激活函数 → Linear → y</span></span></code></pre></div><p>MoE层中有很多个FFN，每个FFN叫一个expert。router会为每个token选择其中几个expert，例如<code>top_k=2</code>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>token 0 → expert 3、expert 7</span></span>
<span class="line"><span>token 1 → expert 7、expert 1</span></span>
<span class="line"><span>token 2 → expert 3、expert 5</span></span></code></pre></div><p>每个expert都有自己的一套权重矩阵：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>expert 1: W1_up, W1_down</span></span>
<span class="line"><span>expert 3: W3_up, W3_down</span></span>
<span class="line"><span>expert 7: W7_up, W7_down</span></span></code></pre></div><p>所以<code>token 0</code>需要计算：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>token0 × expert3权重</span></span>
<span class="line"><span>token0 × expert7权重</span></span></code></pre></div><h2 id="_2-moe是如何在gpu里计算的" tabindex="-1">2. MoE是如何在gpu里计算的 <a class="header-anchor" href="#_2-moe是如何在gpu里计算的" aria-label="Permalink to &quot;2. MoE是如何在gpu里计算的&quot;">​</a></h2><p>最简单的写法是每个token单独计算：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>token0 × W3</span></span>
<span class="line"><span>token2 × W3</span></span>
<span class="line"><span>token0 × W7</span></span>
<span class="line"><span>token1 × W7</span></span></code></pre></div><p>每次都要从显存读取一次expert权重。一个expert矩阵可能有几十MB，但一次只算1个token，计算量很小，GPU大部分时间都在等数据读入。这就像为了运一个箱子，开一辆大卡车往返一次。</p><p>更好的方法是把选中同一个expert的token放在一起：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[token0, token2] × W3</span></span>
<span class="line"><span>[token0, token1] × W7</span></span></code></pre></div><p>W3只需要读取一次，就可以同时计算多个token。GPU有几千个计算核心，适合批量做矩阵乘法：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[多个token的输入] × [一个expert权重]</span></span></code></pre></div>`,19)])])}const g=a(t,[["render",o]]);export{u as __pageData,g as default};
